def choose(prompt,tiles,answer,reason,**kw): return dict(kind='choose',prompt=prompt,tiles=tiles,answer=answer,reason=reason,**kw)
def order(prompt,tiles,reason,**kw): return dict(kind='order',prompt=prompt,tiles=tiles,answer=list(range(len(tiles))),reason=reason,**kw)
def group(prompt,tiles,groups,answer,reason,**kw):return dict(kind='group',prompt=prompt,tiles=tiles,groups=groups,answer=answer,reason=reason,**kw)
def state(label,kind,value,text,effect,**kw):return dict(label=label,visual=kind,value=value,text=text,effect=effect,**kw)
